design_text:
{
  "site_summary": "A partially shaded courtyard with moderate soil moisture and no pets, designed primarily for rich visual interest and textural contrast.",
  "layout_strategy": "The scheme stacks three vertical layers: trailing shade-loving perennials hang in wall baskets at eye level, structural foliage plants sit in mid-height containers against the walls, and delicate ground-hugging ferns carpet the low floor pots.",
  "combination_logic": "The combination relies on contrasting fine fern fronds with broad hosta leaves and cascading ivies, creating a rhythmic interplay of deep greens, silvers, and chartreuse that shifts across seasons with spring blooms and autumn foliage changes.",
  "zones": [
    {
      "zone_name": "Wall Cascades",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "on south-facing courtyard wall hooks, receiving dappled light for 4 hours a day",
      "plants": [
        {
          "scientific_name": "Hedera helix",
          "common_name": "English Ivy",
          "why": "Thrives in partial shade and provides a reliable trailing habit.",
          "role_in_combination": "Cascades downwards to soften the harsh edges of containers and adds permanent deep green structure."
        },
        {
          "scientific_name": "Lysimachia nummularia",
          "common_name": "Creeping Jenny",
          "why": "Loves moderate moisture and brightens dark walls.",
          "role_in_combination": "Offers a bright chartreuse colour contrast against the darker ivy leaves."
        }
      ],
      "maintenance": [
        "Water thoroughly when the top inch of soil feels dry.",
        "Feed with a balanced liquid fertilizer monthly during spring and summer.",
        "Trim trailing stems twice a year to maintain desired length."
      ]
    },
    {
      "zone_name": "Mid-Level Foliage",
      "zone_role": "focal",
      "layer": "mid",
      "placement": "against the main courtyard perimeter wall, in knee-high planters receiving dappled shade",
      "plants": [
        {
          "scientific_name": "Hosta plantaginea",
          "common_name": "August Lily",
          "why": "Brings lush tropical-looking foliage well-suited for partial shade.",
          "role_in_combination": "Provides massive structural leaves that contrast sharply with fine ferns and trailing vines."
        },
        {
          "scientific_name": "Brunnera macrophylla",
          "common_name": "Siberian Bugloss",
          "why": "Adds heart-shaped foliage and delicate blue flowers.",
          "role_in_combination": "Silver-veined leaves reflect indirect light, brightening the shaded wall."
        }
      ],
      "maintenance": [
        "Keep soil consistently moist but never waterlogged.",
        "Remove spent flower stalks in late spring.",
        "Divide overcrowded hosta clumps every three years in early spring."
      ]
    },
    {
      "zone_name": "Ground Carpet",
      "zone_role": "groundcover",
      "layer": "ground",
      "placement": "at floor level along the courtyard paving edges, in low wide bowls in deep shade",
      "plants": [
        {
          "scientific_name": "Adiantum pedatum",
          "common_name": "Northern Maidenhair Fern",
          "why": "Prefers cool, moist, shaded conditions at ground level.",
          "role_in_combination": "Delicate wire-like stems and fan-shaped fronds create an ethereal, fine-textured carpet."
        }
      ],
      "maintenance": [
        "Mist foliage during dry summer spells to maintain humidity.",
        "Clear away old fronds in late winter to make way for new spring growth.",
        "Repot into a slightly larger container every two years."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels across all containers and water deeply",
      "frequency": "twice a week in summer, weekly in spring and autumn",
      "season": "summer"
    },
    {
      "task": "Apply a dilute organic liquid fertilizer to mid-level and hanging containers",
      "frequency": "monthly",
      "season": "spring"
    },
    {
      "task": "Clear away fallen autumn debris from the groundcover pots to prevent fungal issues",
      "frequency": "bi-weekly",
      "season": "autumn"
    }
  ],
  "care_cautions": [
    "Overwatering the hanging wall baskets can lead to root rot if drainage holes become blocked by debris.",
    "The delicate fronds of the Maidenhair Fern in the Ground Carpet zone can scorch or dry out completely if exposed to unexpected direct afternoon sun.",
    "The Hosta leaves in the Mid-Level zone may suffer from slug damage during prolonged wet spells in spring."
  ],
  "pet_safety_note": "No pets live in this household, so traditional pet toxicity restrictions are not required for this design."
}
